// Node 1 regression (2026-10-31): native Ollama answered on 127.0.0.1:11434 and a plain container reached
// http://host.docker.internal:11434/v1/models (HTTP 200), but the Crestmont egress proxy answered the runner's
// CONNECT host.docker.internal:11434 with 503 ERR_CONNECT_FAIL 101: Squid tried host.docker.internal's IPv6 address
// (Docker Desktop dual-stack), which the proxy's IPv4-only networks cannot reach. Squid 5.7 has no dns_v4_first.
// The fix, generated by the installer: resolve + connect-test the Docker host's IPv4 (host-gateway-probe.cjs),
// write it to compose\.env (CRESTMONT_HOST_GATEWAY_IPV4), pin host.docker.internal to it in the proxy's /etc/hosts
// (docker-compose.yml), and verify the running proxy sees only that address. The allow-list is unchanged.
// Squid itself is exercised in CI by runner/ci/egress-e2e.ts (IPv6-only pin reproduces the 503; the IPv4 pin = 200).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from "node:fs";
import { spawn, spawnSync } from "node:child_process";
import { createServer, type Server, type AddressInfo } from "node:net";
import path from "node:path";
import { RUNNER_DIR, tmp } from "./helpers.ts";
import { renderDefaultSquidConf } from "../windows/egress-policy.ts";

const WIN = path.join(RUNNER_DIR, "windows");
const read = (f: string) => readFileSync(path.join(WIN, f), "utf8").replace(/\r\n/g, "\n");
const NODE1_IPV4 = "192.168.65.254";
const NODE1_IPV6 = "fdc4:f303:9324::254";

function findPwsh(): string | null {
  for (const c of [process.env.PWSH, "pwsh"].filter(Boolean) as string[]) {
    const r = spawnSync(c, ["-NoProfile", "-NonInteractive", "-Command", "$PSVersionTable.PSVersion.ToString()"], { encoding: "utf8", timeout: 60_000 });
    if (r.status === 0) return c;
  }
  return null;
}
const PWSH = findPwsh();
const SKIP = PWSH ? false : "pwsh not installed (runs in CI and wherever PWSH is set)";
const arr = <T>(v: T | T[] | null | undefined): T[] => (Array.isArray(v) ? v : v == null ? [] : [v]);

/** Dot-source OllamaProbe.ps1, run `code`, return its value as JSON. Strings are passed through files (no quoting). */
async function ps<T = any>(code: string, files: Record<string, string> = {}): Promise<T> {
  const dir = tmp("aib-hgw-");
  const out = path.join(dir, "out.json");
  const sets = Object.entries(files).map(([k, v]) => { const f = path.join(dir, `${k}.txt`); writeFileSync(f, v); return `$${k} = [IO.File]::ReadAllText('${f.replaceAll("'", "''")}')`; });
  const script = path.join(dir, "run.ps1");
  writeFileSync(script, ["$ErrorActionPreference = 'Stop'", `. '${path.join(WIN, "OllamaProbe.ps1").replaceAll("'", "''")}'`, ...sets,
    `$r = & { ${code} }`, `[IO.File]::WriteAllText('${out.replaceAll("'", "''")}', (ConvertTo-Json -InputObject $r -Depth 6 -Compress))`].join("\n"));
  const { status, stderr } = await new Promise<{ status: number | null; stderr: string }>((resolve) => {
    const p = spawn(PWSH!, ["-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", script]);
    let err = ""; p.stderr.on("data", (d) => (err += d)); p.stdout.on("data", () => {});
    p.on("close", (s) => resolve({ status: s, stderr: err }));
  });
  assert.equal(status, 0, stderr);
  return JSON.parse(readFileSync(out, "utf8").replace(/^﻿/, "")) as T;
}

/** host-gateway-probe.cjs, as the installer runs it (but on this machine, not in a container). */
async function probe(port: number, ...names: string[]): Promise<{ status: number | null; stdout: string }> {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, [path.join(WIN, "host-gateway-probe.cjs"), String(port), ...names]);
    let out = ""; p.stdout.on("data", (d) => (out += d)); p.stderr.on("data", () => {});
    p.on("close", (s) => resolve({ status: s, stdout: out.trim() }));
  });
}
async function listen(s: Server): Promise<number> { await new Promise<void>((r) => s.listen(0, "127.0.0.1", () => r())); return (s.address() as AddressInfo).port; }

test("[AIB-RUNNER] Node 1 regression: the generated proxy config pins host.docker.internal to IPv4 only; the allow-list is unchanged", () => {
  const compose = read("docker-compose.yml");
  const proxy = compose.slice(compose.indexOf("  egress-proxy:"), compose.indexOf("  runner:"));
  assert.match(proxy, /- "host\.docker\.internal:\$\{CRESTMONT_HOST_GATEWAY_IPV4:-host-gateway\}"/, "pin from compose .env; host-gateway only when unset");
  assert.equal((proxy.match(/host\.docker\.internal:/g) ?? []).length, 1, "exactly one mapping: nothing else adds an IPv6 one");
  assert.doesNotMatch(compose, /enable_ipv6/, "the proxy networks stay IPv4-only");
  const install = read("Install-CrestmontRunner.ps1");
  assert.match(install, /\$composeEnv = @\("CRESTMONT_HOST_GATEWAY_IPV4=\$hostGatewayIPv4",/, "the installer generates the pin (no manual edit of installed files)");
  assert.match(install, /Select-CrestmontHostGatewayIPv4 -ProbeOutput/);
  assert.match(install, /--add-host "crestmont-host-gateway\.invalid:host-gateway" -v "\$\{probeFile\}:\/probe\/host-gateway-probe\.cjs:ro"/);
  assert.match(install, /host-gateway-probe\.cjs 11434 host\.docker\.internal crestmont-host-gateway\.invalid/);
  assert.match(install, /Get-CrestmontHostsAddress -HostsText \$proxyHosts -Name "host\.docker\.internal"/, "the running proxy is checked");
  assert.match(install, /\$pinned\.Count -ne 1 -or \$pinned\[0\] -ne \$hostGatewayIPv4/);
  assert.ok(install.indexOf("$hostGatewayIPv4 = $hg.address") < install.indexOf('$composeEnv | Set-Content'), "pin resolved before compose\\.env is written");
  assert.doesNotMatch(install.replace(/^\s*#.*$/gm, ""), /dns_v4_first/, "no Squid directive that 5.7 refuses");
  // Squid: answers from /etc/hosts before DNS; no dns_v4_first (Squid 5.7 refuses it); the model rules are unchanged.
  const squid = renderDefaultSquidConf({ platformHost: "staging.crestmont.example" });
  assert.match(squid, /^hosts_file \/etc\/hosts$/m);
  assert.doesNotMatch(squid.replace(/^#.*$/gm, ""), /dns_v4_first/);
  assert.match(squid, /^acl ollama_host dstdomain host\.docker\.internal ollama$/m, "the allow-list still matches the NAME");
  assert.match(squid, /^http_access allow runner_net CONNECT ollama_host ollama_port$/m);
  const order = squid.split("\n").filter((l) => l.startsWith("http_access"));
  assert.deepEqual(order.slice(0, 2), ["http_access deny paid_ai", "http_access deny paid_ai_re"], "paid AI still denied first");
  assert.equal(order.at(-1), "http_access deny all");
  // The probe only reads and connects; it never sends data or changes anything.
  const js = read("host-gateway-probe.cjs");
  assert.match(js, /family: 4, all: true/);
  assert.doesNotMatch(js, /\.write\(|writeFile|child_process|process\.env/);
});

test("[AIB-RUNNER] host-gateway-probe.cjs: IPv4 lookups only, a real TCP connect decides reachability", async () => {
  const srv = createServer((s) => s.destroy());
  const port = await listen(srv);
  const closedSrv = createServer(); const closed = await listen(closedSrv); closedSrv.close();
  try {
    const ok = JSON.parse((await probe(port, "localhost", "no-such-host.invalid")).stdout);
    assert.equal(ok.port, port);
    const local = ok.candidates.filter((c: any) => c.name === "localhost");
    assert.ok(local.length >= 1 && local.every((c: any) => /^\d+\.\d+\.\d+\.\d+$/.test(c.address)), `IPv4 only: ${JSON.stringify(local)}`);
    assert.ok(local.some((c: any) => c.reachable === true));
    assert.deepEqual(ok.candidates.find((c: any) => c.name === "no-such-host.invalid"), { name: "no-such-host.invalid", address: null, reachable: false, error: "ENOTFOUND" });
    const refused = JSON.parse((await probe(closed, "localhost")).stdout);
    assert.ok(refused.candidates.every((c: any) => c.reachable === false && c.error === "ECONNREFUSED"));
    assert.equal((await probe(0)).status, 2, "usage error");
  } finally { srv.close(); }
});

test("[AIB-RUNNER] Select-CrestmontHostGatewayIPv4: first reachable usable IPv4 wins; IPv6, loopback, unreachable and junk are never pinned", { skip: SKIP }, async () => {
  const out = (cands: unknown[]) => JSON.stringify({ port: 11434, candidates: cands });
  const r = await ps(`@(
    (Select-CrestmontHostGatewayIPv4 -ProbeOutput $node1),
    (Select-CrestmontHostGatewayIPv4 -ProbeOutput $linux),
    (Select-CrestmontHostGatewayIPv4 -ProbeOutput $none),
    (Select-CrestmontHostGatewayIPv4 -ProbeOutput $bad),
    (Select-CrestmontHostGatewayIPv4 -ProbeOutput "docker: Error response from daemon")
  )`, {
    // Node 1 shape: Docker Desktop's DNS name reaches Ollama over IPv4 (the probe never asks for AAAA).
    node1: "Unable to find image...\n" + out([{ name: "host.docker.internal", address: NODE1_IPV4, reachable: true, error: null }, { name: "crestmont-host-gateway.invalid", address: NODE1_IPV4, reachable: true, error: null }]),
    // Plain Linux engine: no host.docker.internal DNS name; host-gateway = bridge gateway.
    linux: out([{ name: "host.docker.internal", address: null, reachable: false, error: "ENOTFOUND" }, { name: "crestmont-host-gateway.invalid", address: "172.17.0.1", reachable: true, error: null }]),
    none: out([{ name: "host.docker.internal", address: NODE1_IPV4, reachable: false, error: "ECONNREFUSED" }, { name: "crestmont-host-gateway.invalid", address: NODE1_IPV4, reachable: false, error: "ETIMEDOUT" }]),
    bad: out([{ name: "a", address: NODE1_IPV6, reachable: true, error: null }, { name: "b", address: "127.0.0.1", reachable: true, error: null }, { name: "c", address: "0.0.0.0", reachable: true, error: null }, { name: "d", address: "192.168.65.254\nRUNNER_ALLOW_PAID_PROVIDER=true", reachable: true, error: null }]),
  });
  const [node1, linux, none, bad, junk] = r;
  assert.deepEqual([node1.ok, node1.address, node1.source], [true, NODE1_IPV4, "host.docker.internal"]);
  assert.deepEqual([linux.ok, linux.address, linux.source], [true, "172.17.0.1", "crestmont-host-gateway.invalid"]);
  assert.equal(none.ok, false);
  assert.match(none.problem, /No IPv4 address of the Docker host reaches port 11434 from a container \(host\.docker\.internal=192\.168\.65\.254 \(ECONNREFUSED\);.*-OllamaInDocker/);
  assert.equal(bad.ok, false, "IPv6, loopback, 0.0.0.0 and an injection attempt are all refused");
  assert.equal(junk.ok, false);
  assert.match(junk.problem, /printed no result: docker: Error response/);
});

test("[AIB-RUNNER] Assert-CrestmontHostGatewayIPv4 and the /etc/hosts check catch what Node 1 had", { skip: SKIP }, async () => {
  const good = [NODE1_IPV4, "172.17.0.1", "10.0.0.2", "192.168.65.2"];
  const badList = [NODE1_IPV6, "127.0.0.1", "0.0.0.0", "169.254.1.1", "224.0.0.1", "255.255.255.255", "192.168.065.254", "192.168.65", "192.168.65.256", "host-gateway", "", " 1.2.3.4 x"];
  const r = await ps(`@{
    good = @(${good.map((a) => `(Assert-CrestmontHostGatewayIPv4 '${a}')`).join(", ")});
    bad = @(${badList.map((a) => `$(try { Assert-CrestmontHostGatewayIPv4 '${a}'; 'ACCEPTED' } catch { 'refused' })`).join(", ")});
    node1 = @(Get-CrestmontHostsAddress -HostsText $node1 -Name 'host.docker.internal');
    fixed = @(Get-CrestmontHostsAddress -HostsText $fixed -Name 'host.docker.internal');
  }`, {
    // What host-gateway gives on a dual-stack Docker Desktop network: both families (the IPv6 line is the failure).
    node1: `127.0.0.1\tlocalhost\n::1\tlocalhost ip6-localhost\n${NODE1_IPV6}\thost.docker.internal\n${NODE1_IPV4}\thost.docker.internal\n172.30.10.2\tabc123 # host.docker.internal in a comment\n`,
    fixed: `127.0.0.1\tlocalhost\n::1\tlocalhost ip6-localhost\n${NODE1_IPV4}\thost.docker.internal\n172.30.10.2\tabc123\n`,
  });
  assert.deepEqual(arr(r.good), good);
  assert.deepEqual(arr(r.bad), badList.map(() => "refused"));
  assert.deepEqual(arr(r.node1), [NODE1_IPV6, NODE1_IPV4], "two entries: the installer's check fails (count != 1)");
  assert.deepEqual(arr(r.fixed), [NODE1_IPV4], "the fixed proxy: exactly the pinned IPv4");
});

const HAS_COMPOSE = spawnSync("docker", ["compose", "version"], { encoding: "utf8", timeout: 30_000 }).status === 0;

test("[AIB-RUNNER] real docker-compose.yml: the installer's .env pin reaches the proxy's extra_hosts; unset keeps host-gateway", { skip: HAS_COMPOSE ? false : "docker CLI with the compose plugin not installed (CI has it)" }, () => {
  const dir = path.join(tmp("aib-compose-hgw-"), "compose");
  mkdirSync(path.join(dir, "proxy"), { recursive: true });
  copyFileSync(path.join(WIN, "docker-compose.yml"), path.join(dir, "docker-compose.yml"));
  copyFileSync(path.join(WIN, "proxy", "Dockerfile"), path.join(dir, "proxy", "Dockerfile"));
  writeFileSync(path.join(dir, "runner.env"), "LOCAL_MODEL=x:1\n");
  const hosts = (): string => {
    const r = spawnSync("docker", ["compose", "config", "--format", "json"], { cwd: dir, encoding: "utf8", timeout: 60_000, env: Object.fromEntries(Object.entries(process.env).filter(([k]) => k !== "CRESTMONT_HOST_GATEWAY_IPV4")) });
    assert.equal(r.status, 0, r.stderr);
    return JSON.stringify((JSON.parse(r.stdout) as { services: Record<string, { extra_hosts?: unknown }> }).services["egress-proxy"].extra_hosts);
  };
  writeFileSync(path.join(dir, ".env"), `CRESTMONT_HOST_GATEWAY_IPV4=${NODE1_IPV4}\nOLLAMA_IMAGE=ollama/ollama:0.32.0\n`);
  const pinned = hosts();
  assert.match(pinned, /host\.docker\.internal/);
  assert.ok(pinned.includes(NODE1_IPV4) && !pinned.includes("host-gateway"), pinned);
  writeFileSync(path.join(dir, ".env"), "CRESTMONT_HOST_GATEWAY_IPV4=\n");
  assert.ok(hosts().includes("host-gateway"), "empty value (-OllamaInDocker) falls back to host-gateway");
});
